// ---------------------------------------------------------------------------
// Sales History feature types — explicit interfaces, never Drizzle inference
// ---------------------------------------------------------------------------

/** A single sale record as returned by GET /api/sales.
 * Keys match Drizzle camelCase property names (backend serialises via Object.fromEntries). */
export interface SaleRecord {
  id: string
  saleNumber: string // e.g. "SA-0042"
  customerId: string | null
  sourceType: string
  sourceId: string | null
  status: 'completed' | 'voided'
  subtotalNet: number // ex-tax cents
  vatTotal: number // VAT in cents
  totalGross: number // incl-tax cents
  createdAt: string // ISO timestamp
}

/** Response shape for GET /api/sales */
export interface SalesListResponse {
  sales: SaleRecord[]
  total: number
}

/** Error response from PATCH /api/sales/:id/void */
export interface VoidError {
  error: string
  code?: 'NOT_FOUND' | 'ALREADY_VOIDED' | 'INTERNAL_ERROR'
}

/** Shape of customer lookup cache (id → displayName) */
export interface CustomerNameMap {
  [id: string]: string
}
